n("ליבא", "ליבא בא מהמילה היידית ליב, שפירושה אהבה, והיא קרובה למילה הגרמנית בעלת אותה משמעות. זה שם מקהילות אשכנז, ששם נבנו שמות רבים ביידיש ממילים של אהבה, יופי וחיים, לצד השמות העבריים. ליבה הוא כתיב אחר של אותו שם.", ["ליבה"])
n("חוה", "השם קשור למילה חיים, ובתורה האדם קרא לאשתו חוה, כי היא הייתה האם של כל החיים. בסיפור הבריאה חוה היא האישה הראשונה, אשתו של אדם ואמם של קין, הבל ושת. בעברית יש גם פועל אחר, חיווה, לומר ולהביע, ומכאן חוות דעת, אבל זו מילה אחרת.")
n("סול", "סול היא השמש בלטינית, ומאותה מילה באות בשפות אירופה מילים רבות שעניינן השמש, כמו המילה סולארי, שהגיעה גם לעברית. בשפה הספרדית ובפורטוגזית סול היא גם המילה היומיומית לשמש. במוזיקה סול הוא גם שמו של אחד הצלילים בסולם.")
n("אודיה", "אודיה בנוי מהפועל אודה, אני מודה ומשבח, ומשם האל, ופירושו אודה לה׳. בתהילים המילה מופיעה בתמונה של שערים שנפתחים, ומי שנכנס בהם מודה לה׳. מאותו שורש, י־ד־ה, באות גם המילים תודה והודיה, ומאותה מילה נבנו גם השמות יהודה והודיה.", ["הודיה"])
n("כפיר", "כפיר הוא אריה צעיר, ובמקרא המילה מופיעה פעמים רבות לצד אריה ולביא. בספר שופטים שמשון פוגש בדרכו לתמנה אריה צעיר ששואג לעברו, וקורע אותו בידיו. בעברית המקראית יש כמה מילים לאריה, ולכל אחת גוון משלה, כמו ארי, לביא וליש.")
n("ליאל", "ליאל בנוי משתי מילים קצרות, לי ואל, ופירושו אלוהים שלי. אל היא אחת המילים העתיקות לאלוהים בשפות השמיות, ושמות עבריים רבים נגמרים בה, כמו אוריאל ועזריאל. באותה פתיחה, לי, נבנו גם שמות כמו ליאור וליאת. השם ניתן לבנים ולבנות.")
n("סהר", "סהר הוא ירח, מילה עתיקה ונדירה יותר מהמילה ירח. בשיר השירים המילה מופיעה בצירוף אגן הסהר, כלי עגול כמו הירח המלא. מאותה מילה באות גם המילה סהרורי, מי שהולך בשנתו, כאילו בהשפעת הירח, והצירוף חצי סהר, צורת הירח הדקה. השם ניתן לבנים ולבנות.")
n("שולמית", "שולמית היא הנערה שאליה פונים בשיר השירים, וזה המקום היחיד במקרא שבו השם מופיע. החוקרים אינם בטוחים מה מקורו: יש שקשרו אותו לשלום ולשלמות, ויש שקשרו אותו לשונם, כפר עתיק בעמק יזרעאל. לפי הפירוש הראשון, מאותו שורש, ש־ל־ם, באים גם שלום ושלמה.")
n("עידן", "עידן הוא תקופה ארוכה, והמילה באה מהארמית, שבה עידן הוא זמן או מועד. בספר דניאל, שחלקו כתוב ארמית, המילה מופיעה כמה פעמים במובן של זמן קבוע ומוגדר. בעברית של היום עידן הוא תקופה שלמה בהיסטוריה, כמו בצירוף עידן המחשב.")
n("אביאל", "השם מחבר את המילה אבי עם שם האל, ופירושו אלוהים הוא אבי. בספר שמואל אביאל הוא אביו של קיש, וכך גם סבו של שאול, המלך הראשון של ישראל. באותה דרך נבנה גם השם אליאב, שמחבר את אותן שתי מילים בסדר הפוך.")
n("סולימאן", "סולימאן הוא הצורה הערבית של השם שלמה, ושני השמות באים מאותו שורש שמי, ש־ל־ם, שעניינו שלום ושלמות. בערבית אותו שורש נמצא גם במילים סלאם, שלום, וסלים, שלם ובריא. השם מוכר גם בטורקית ובפרסית, בצורות קרובות.", ["שלמה"])
n("שיר", "שיר הוא מילים ששרים בלחן, וגם יצירה כתובה בשורות ובקצב. במקרא המילה מופיעה פעמים רבות, ובתהילים יש מזמורים רבים שנפתחים במילה שיר, כמו שיר המעלות. מאותה מילה נבנו גם שירה, שירי ושיראל.", ["שירה", "שירי", "שיראל"])
n("מילה", "בשפות סלאביות רבות המילה מיל פירושה יקר ואהוב, וממנה נבנו שמות כמו מילה, מילנה ולודמילה. בעברית מילה היא יחידה של דיבור ושל כתיבה, מהשורש מ־ל־ל, שממנו באות גם המילים מלל ומילולי. כך לשם יש שני מקורות שונים, שנשמעים אותו דבר.", ["מילא"])
n("שושנה", "שושנה היא פרח, ובשיר השירים המילה חוזרת כמה פעמים, למשל בתמונה של שושנה שגדלה בין החוחים. החוקרים אינם בטוחים איזה פרח היא שושנה של המקרא, ויש שקשרו את המילה למילה מצרית עתיקה לפרח הלוטוס. בעברית של היום שושנה היא גם ורד, ושושן הוא שם של סוג פרחים.")
n("רותם", "רותם הוא שיח מדבר עם ענפים ירוקים ודקים, שבסוף החורף מתכסה בפריחה לבנה וריחנית. בספר מלכים אליהו הנביא בורח למדבר, יושב תחת רותם ונרדם שם. בארץ הרותם גדל בנגב, בערבה ובחולות שלאורך החוף. השם ניתן לבנים ולבנות.")
n("אליעזר", "השם מחבר את המילה אלי עם עזר, ופירושו אלוהיי הוא העזרה שלי. בתורה אליעזר הוא בנו השני של משה וציפורה, ומשה קרא לו כך כי אלוהים הציל אותו מחרב פרעה. בספר בראשית מוזכר גם אליעזר מדמשק, מבני ביתו של אברם. מאותה מילה נבנה גם השם אלעזר.", ["אלעזר"])
n("איה", "בערבית איה היא סימן ואות, וגם המילה לפסוק בקוראן. בעברית איה היא עוף דורס, שמוזכר כבר במקרא ברשימת העופות. השם קצר, ואפשר לשמוע בו גם את מילת השאלה העברית איה, כלומר איפה, אבל המילים באו ממקורות שונים.")
n("ג'וד", "ג'וד היא מילה ערבית שפירושה נדיבות, נתינה ברוחב לב. מאותו שורש באות בערבית גם המילים ג'יד, טוב, וג'ודה, איכות. באנגלית ג'וד הוא שם אחר לגמרי, שבא מהשם יהודה, ולכן אותן אותיות יכולות לשאת שני שמות שונים.")
n("דין", "בעברית דין הוא משפט, וגם החוק שעליו המשפט נשען, ומכאן בית דין ועורך דין. בערבית דין היא דת, ובארמית דין הוא משפט, כמו בעברית. מאותו שורש עברי, ד־י־ן, נבנו גם השמות דן ודינה. השם קצר ונשמע אותו דבר בשתי השפות.", ["דינה"])
n("פנחס", "פנחס הוא שם מקראי עתיק, וכנראה מקורו במצרית, שבה פירושו הנובי, איש מארץ כוש. בתורה פנחס הוא בנו של אלעזר הכהן ונכדו של אהרן, ובספר במדבר מסופר שבזכותו נעצרה מגפה במחנה. בספרות חז״ל מוזכרים כמה חכמים בשם פנחס.")
n("יחיא", "יחיא הוא הצורה הערבית של השם יוחנן, שפירושו ה׳ חנן. בערבית השם נשמע כמו הפועל יחיא, יחיה, מהשורש ח־י־י, ומאותו שורש באות גם המילים העבריות חי וחיים. כך השם מחבר בין שם עברי עתיק לבין מילה ערבית מוכרת.", ["יוחנן"])
n("שיינא", "שיינא בא מהמילה היידית שיין, שפירושה יפה, והיא קרובה למילה הגרמנית בעלת אותה משמעות. בקהילות אשכנז נבנו כך שמות רבים ממילים ביידיש, כמו ליבא, מהמילה אהבה. שיינה הוא כתיב אחר של אותו שם.", ["שיינה"])
n("רוי", "רוי הוא שם שמקורו בשפה הגאלית של סקוטלנד ואירלנד, במילה שפירושה אדום, ואולי ניתן בתחילה למי ששערו אדום. בצרפתית העתיקה רוי פירושו מלך, ויש שקשרו אליו את השם, אבל המקור הגאלי מקובל יותר. בעברית השם קצר ונכתב בשלוש אותיות.")
n("אמיליה", "אמיליה בא משם המשפחה הרומי אמיליוס, אחת המשפחות העתיקות של רומא. מקור השם הרומי אינו ודאי, ויש שקשרו אותו למילה לטינית שפירושה מתחרה. על שם המשפחה נקראה הדרך הרומית ויה אמיליה, ועל שם הדרך נקרא האזור אמיליה בצפון איטליה. מאותו שם נבנו גם אמילי, אמלי ואמיל.", ["אמילי", "אמלי", "אמיל"])
n("יסמין", "יסמין הוא שיח מטפס עם פרחים לבנים קטנים, שריחם חזק במיוחד בערב. השם עבר מהפרסית לערבית, ומשם לשפות רבות באירופה. מהפרחים מכינים בושם, ובמקומות רבים מוסיפים אותם גם לתה. יסמינה היא צורה של אותו שם.", ["יסמינה"])
n("אלרואי", "השם מחבר את המילה אל עם רואי, ופירושו האל שרואה אותי. בתורה זו הקריאה של הגר, שפחתה של שרי, כשמלאך ה׳ מצא אותה במדבר ליד מעיין מים. על שם המעשה נקרא המקום באר לחי רואי. מאותו שורש, ר־א־ה, באות גם המילים ראייה ומראה.")
n("יולי", "יולי הוא שמו של החודש השביעי בלוח הלועזי, שנקרא על שם בן למשפחת יוליוס הרומית העתיקה. מאותו שם רומי באו בשפות שונות גם שמות כמו יוליה וג'וליה. מקור השם יוליוס אינו ודאי, ויש שקשרו אותו למילה יוונית שמתארת זקן ראשון ורך.")
n("מוריה", "מוריה הוא שם של הר בירושלים, ובתורה אברהם הולך אל ארץ המוריה עם בנו יצחק. בדברי הימים זה ההר שעליו בנה שלמה את בית המקדש. מקור השם אינו ודאי: יש שקשרו אותו לפועל ראה, ויש שקשרו אותו למילה הוראה, לימוד.")
n("הלני", "הלני היא צורה של השם היווני הלנה, שמקובל לקשר למילה יוונית שפירושה לפיד או אור, אבל המקור אינו ודאי. דרך היוונית והלטינית עבר השם לשפות רבות, ובכל אחת קיבל צורה משלו, כמו הלן ואלנה. הלני והילני הן שתי דרכים לכתוב אותו שם בעברית.", ["הלן", "הילני"])
n("כרמי", "כרמי פירושו הכרם שלי, והשם בנוי על המילה כרם, שדה של גפנים, עם סיומת של שייכות. בשיר השירים הנערה אומרת שלא שמרה על הכרם שלה, כי שלחו אותה לשמור על כרמים של אחרים. בתורה כרמי הוא גם שמו של אחד מבניו של ראובן. השם ניתן לבנים ולבנות.", ["כרם"])
n("גלי", "גלי פירושו הגלים שלי, והשם בנוי על המילה גל, גל של ים, עם סיומת של שייכות. בספר ישעיהו גלי הים הם תמונה של צדקה ושל שפע שאינם נגמרים. בעברית גל הוא גם ערמה של אבנים, ומכאן המילה גלעד. מאותה מילה נבנו גם גל וגליה.", ["גל", "גליה"])
n("נדב", "נדב בא מהשורש נ־ד־ב, שעניינו נתינה מרצון ומלב טוב, ומכאן המילים נדבה ונדיבות. בתורה נדב הוא בנו הבכור של אהרן, אחיו של אביהוא, אלעזר ואיתמר. בתנ״ך זה גם שמו של אחד ממלכי ישראל, בנו של ירבעם.")
n("ברוך", "ברוך פירושו מבורך, והשם בא מהשורש ב־ר־ך, שממנו באות גם המילים ברכה ומבורך. בספר ירמיהו ברוך בן נריה הוא הסופר שכתב מפי ירמיהו את דבריו על מגילה. בתפילה היהודית המילה ברוך פותחת את רוב הברכות.")
n("גל", "לגל יש שתי משמעויות בעברית: גל של מים בים או בנהר, וגם ערמה של אבנים. בספר בראשית יעקב ולבן עושים גל של אבנים לעדות על הברית ביניהם, ויעקב קורא לו גלעד. מאותה מילה נבנו גם גלי וגליה. השם ניתן לבנים ולבנות.", ["גלי", "גליה"])
n("שמחה", "שמחה היא רגש של טוב ושל אושר, מהשורש ש־מ־ח, שממנו באות גם המילים שמח ומשמח. בתהילים יש מזמור שבו העבודה לה׳ נעשית בשמחה ובשירה. בעברית של היום המילה משמשת גם לאירוע משפחתי, כמו חתונה, בצירוף שמחה משפחתית. השם ניתן לבנים ולבנות.")
n("נפתלי", "בתורה נפתלי הוא בנו של יעקב ובלהה, שפחת רחל, ורחל קראה לו כך בגלל המאבק שהיה לה עם אחותה. השם בא מהשורש פ־ת־ל, שעניינו התפתלות, ומאותו שורש באה גם המילה פתיל. ממנו יצא שבט נפתלי, שנחלתו הייתה בגליל.")
n("פלג", "פלג הוא נחל קטן או תעלה של מים, ובתהילים המילה מופיעה בתמונה של עץ ששתול על פלגי מים. בספר בראשית פלג הוא אחד מצאצאיו של שם, ושמו מוסבר בכך שבימיו נחלקה הארץ. מאותו שורש באות גם המילים מפלגה ופילוג.")
n("בתיה", "השם מחבר את המילה בת עם שם האל, ופירושו בתו של ה׳. בדברי הימים בתיה מוזכרת כבת פרעה, שנישאה למרד משבט יהודה. במדרש מזהים את בתיה עם בת פרעה שמשתה את משה מהיאור, ומסבירים שקיבלה את שמה מפני שגידלה אותו.", ["ביתיה"])
n("אמונה", "אמונה היא נאמנות, יציבות וביטחון, מהשורש א־מ־ן, שממנו באות גם המילים אמת, אמן ונאמן. בעברית המקראית המילה מתארת לרוב יושר ונאמנות, כמו בספר חבקוק, שבו הצדיק חי באמונתו. בתורה המילה מתארת גם את ידיו של משה, שנשארו יציבות עד השקיעה.")
n("טל", "טל הוא טיפות המים הקטנות שמופיעות על הצמחים בלילות ובבקרים, גם בקיץ, כשאין גשם. בארץ ישראל הטל חשוב לחקלאות בחודשי הקיץ, ובתפילה יש ברכה מיוחדת עליו. בשירת האזינו הדיבור משול לטל שיורד בעדינות. מאותה מילה נבנו גם טלי וטליה. השם ניתן לבנים ולבנות.", ["טליה", "טלי"])
n("אלעזר", "השם מחבר את שם האל עם הפועל עזר, ופירושו אלוהים עזר. בתורה אלעזר הוא בנו של אהרן, ואחרי מות אהרן הוא נעשה הכהן הגדול. אלעזר עמד לצד יהושע בחלוקת הארץ לשבטים. מאותה מילה נבנה גם השם אליעזר, ומאותו פועל באים גם עזרא ועזריאל.", ["אליעזר"])
n("מילאן", "מילאן הוא שם סלאבי שבנוי על המילה מיל, יקר ואהוב, כמו השמות מילה ומילנה. השם מוכר בשפות סלאביות רבות, למשל בצ׳כית ובסרבית, ומילאנה היא הצורה שניתנת לבנות. מילאן הוא גם שמה של עיר גדולה בצפון איטליה, אבל לשם העיר יש מקור אחר לגמרי.", ["מילאנה"])
n("מאסה", "מאסה היא המילה הערבית ליהלום, אבן יקרה ושקופה שנוצרת מפחמן בעומק האדמה. המילה הגיעה לערבית כנראה מהיוונית, מאותו מקור של המילה האנגלית ליהלום. מאסא הוא כתיב אחר של אותו שם בעברית.", ["מאסא"])
n("אליאב", "השם מחבר את המילה אלי עם אב, ופירושו אלוהים הוא אבי. בספר במדבר אליאב בן חלון הוא הנשיא של שבט זבולון. בספר שמואל אליאב הוא בנו הבכור של ישי, ששמואל הנביא חשב בתחילה שהוא המלך שנבחר, לפני שנבחר דוד. השם אביאל בנוי מאותן מילים, בסדר הפוך.")
n("יחיאל", "השם מחבר את הפועל יחי, יחיה, עם שם האל, ופירושו יחיה האל. מאותו שורש, ח־י־ה, באות המילים חי, חיים ותחייה. באותה דרך נבנו שמות עבריים רבים שמצרפים פועל לשם האל, כמו יחזקאל וישמעאל.")
n("פאטמה", "פאטמה היא שם ערבי עתיק, מהשורש פ־ט־ם, שעניינו גמילה, הפסקת ההנקה. השם מוכר בעולם הערבי ובשפות רבות נוספות, כמו טורקית ופרסית, בצורות שונות. פאטימה הוא כתיב אחר של אותו שם בעברית.", ["פאטימה"])
n("אוסיד", "אוסיד היא צורת הקטנה של המילה הערבית אסד, אריה, ולכן פירושו אריה קטן או אריה צעיר. צורות הקטנה כאלה, עם יוד באמצע המילה, מוכרות בערבית גם בשמות פרטיים אחרים, כמו חוסיין, שבנוי על חסן. בעברית יש למילה מקבילה, כפיר.")
n("עמיחי", "השם מחבר את המילה עמי, העם שלי, עם המילה חי, ופירושו העם שלי חי. מאותו שורש, ח־י־ה, באות המילים חיים ותחייה. באותה דרך נבנו שמות עבריים רבים שנפתחים במילה עמי, כמו עמיאל ועמירם.")
n("זינה", "זינה היא מילה ערבית שפירושה קישוט ויופי, וגם תכשיט. מאותו שורש, ז־י־ן, באה המילה זיין, יופי וחן, וממנה השם זיין, שם לבנים. בערבית של היום המילה משמשת גם לקישוטים של חג, שתולים ברחובות ובבתים. זיינה הוא כתיב אחר של אותו שם.", ["זיין", "זיינה"])
n("חסן", "חסן היא מילה ערבית שפירושה טוב ונאה, מהשורש ח־ס־ן, שעניינו יופי וטוב. מאותו שורש באים בערבית גם השמות חוסיין ומוחסן, והמילה אחסן, טוב יותר. בעברית יש מילה שנשמעת דומה, חוסן, כוח ועמידות, אבל המשמעות שלה שונה.")
n("ליאור", "ליאור בנוי משתי מילים, לי ואור, ופירושו יש לי אור. מאותה מילה, אור, נבנו שמות עבריים רבים, כמו אורי, אוריאל ומאור, וליאורה היא הצורה שניתנת לבנות. באותה פתיחה, לי, נבנו גם ליאת וליאל. השם ניתן לבנים ולבנות.", ["ליאורה"])
n("רז", "רז הוא סוד, מילה שהגיעה לעברית מהארמית, ואולי לפני כן מהפרסית. בעברית של חז״ל ובשירה המילה מתארת לרוב דבר עמוק ונסתר, ומכאן גם רזים, סודות. מאותה מילה נבנו גם השמות רזיאל ואלירז. השם ניתן לבנים ולבנות.", ["רזיאל", "אלירז"])
n("דביר", "דביר הוא החדר הפנימי בבית המקדש, שנקרא גם קודש הקודשים, ובו עמד ארון הברית. בספר מלכים מתואר איך שלמה בנה את הדביר וציפה אותו זהב. יש שקשרו את המילה לדיבור, ובתנ״ך דביר הוא גם שם של עיר ביהודה.")
n("יהל", "יהל הוא פועל בעברית עתיקה, מהשורש ה־ל־ל, ופירושו יאיר ויזרח, כמו אור של שמש או של כוכב. המילה נדירה, והיא נשמעת היום בעיקר כשם פרטי קצר. מאותה מילה נבנה גם השם יהלי. השם ניתן לבנים ולבנות.", ["יהלי"])
n("גילי", "גילי פירושו השמחה שלי, והשם בנוי על המילה גיל, שמחה, עם סיומת של שייכות. בספר זכריה המילה פותחת קריאה לבת ציון לשמוח מאוד, ושם גילי היא צורת ציווי, קריאה לשמוח. מאותה מילה נבנו גם גיל וגילה.", ["גיל", "גילה"])
n("אילול", "אילול הוא השם של חודש ספטמבר בערבית של הלבנט, בסוריה, בלבנון, בירדן ובארץ ישראל. שמות החודשים האלה באו מהלוח הבבלי, ואילול קרוב בשמו לחודש העברי אלול, שחל בדרך כלל באותה עונה, בסוף הקיץ. איילול הוא כתיב אחר של אותו שם.", ["איילול"])
n("אשר", "בתורה אשר הוא בנו של יעקב וזלפה, שפחת לאה, ולאה קראה לו כך כי אמרה שהנשים יראו אותה מאושרת. ממנו יצא שבט אשר, שנחלתו הייתה בגליל המערבי, לאורך חוף הים. מאותו שורש באות המילים אושר ומאושר.")
n("עקיבא", "עקיבא הוא צורה ארמית של השם יעקב, ושניהם באים מהשורש ע־ק־ב, שממנו באה גם המילה עקב. השם מוכר מתקופת המשנה, שבה היו מקובלים שמות בצורה ארמית שנגמרת באלף, כמו אבא וזירא.", ["יעקב"])
n("אילאף", "אילאף היא מילה ערבית שפירושה קרבה, הרגל וחיבה, מהשורש א־ל־ף, שעניינו התרגלות וחיבור. מאותו שורש באה בערבית גם המילה אולפה, ידידות וקרבה. בעברית השורש מוכר מהמילה אלוף, במובן הישן של חבר קרוב, ומהפועל אילף, לימד והרגיל.")
n("אמיתי", "אמיתי בנוי על המילה אמת, ומאותו שורש, א־מ־ן, באים גם אמונה ונאמן. בתנ״ך אמיתי הוא אביו של יונה הנביא, והוא מוזכר רק בשמו, בלי סיפור משלו. השם נשמע כמו המילה העברית אמיתי, מה שנכון ולא מזויף.")
n("אפרים", "בתורה אפרים הוא בנו השני של יוסף ואסנת, שנולד במצרים, ויוסף קרא לו כך כי אלוהים הפרה אותו בארץ שבה סבל. השם בא מהשורש פ־ר־ה, שממנו באות גם המילים פרי ופריון. ממנו יצא שבט אפרים, ובנביאים אפרים הוא לפעמים שם לכל ממלכת ישראל.")
n("יזן", "יזן הוא שם ערבי עתיק, שמקורו בתימן, בדרום חצי האי ערב. השם קשור למשפחה של אצילים בתימן הקדומה, שבניה נקראו ד'ו יזן, כלומר אלה של יזן. משמעות המילה עצמה אינה ידועה בוודאות. בעברית השם קצר ונכתב בשלוש אותיות.")
n("ינון", "ינון בא מהשורש נ־י־ן, שממנו באה המילה נין, צאצא, ופירושו ימשיך ויתרבה מדור לדור. בתהילים המילה מופיעה בתמונה של שם שימשיך כל עוד השמש זורחת. מאותו שורש באות גם המילים נין ונכד, צאצאים של הדורות הבאים.")
n("אדר", "אדר הוא החודש השנים עשר בלוח העברי, ובו חל חג פורים. בשנה מעוברת יש שני חודשי אדר, אדר א׳ ואדר ב׳. בעברית המקראית אדר הוא גם אדיר ונהדר, ומאותו שורש באה המילה אדרת, גלימה רחבה. השם ניתן לבנים ולבנות.")
n("מיכאלה", "מיכאלה היא הצורה הנשית של מיכאל, שפירושו מי כמו אל, שאלה שהתשובה עליה היא שאין כמו האל. השם מיכאל עבר משפה לשפה, וכך גם הצורה הנשית, שמוכרת בשפות רבות באירופה. במסורת היהודית מיכאל הוא שמו של אחד המלאכים.", ["מיכאל"])

